import type { Department, JobTitle } from '../employee.constants';
import {
  CountryCodeField,
  DepartmentField,
  EmailField,
  FirstNameField,
  JobTitleField,
  LastNameField,
} from './employee-fields';

/** The employee code is generated by the server and is not accepted here. */
export class CreateEmployeeDto {
  @FirstNameField()
  firstName!: string;

  @LastNameField()
  lastName?: string | null;

  @EmailField()
  email?: string | null;

  @CountryCodeField()
  countryCode!: string;

  @DepartmentField()
  department!: Department;

  @JobTitleField()
  jobTitle!: JobTitle;
}
